import { useEffect, useRef } from "react";
import { Button } from "../ui/primitives.jsx";
import { Icon } from "../ui/icons.jsx";

export default function LoginOverlay({ onClose }) {
    const ref = useRef(null);
    useEffect(() => {
        ref.current?.querySelector("input")?.focus();
        const onKey = (event) => event.key === "Escape" && onClose();
        document.addEventListener("keydown", onKey);
        return () => document.removeEventListener("keydown", onKey);
    }, [onClose]);
    return (
        <div className="fixed inset-0 z-(--z-overlay) grid animate-fade-in place-items-center bg-ink-900/50 backdrop-blur-xs" onClick={onClose}>
            <div ref={ref} role="dialog" aria-modal="true" aria-label="E-Mail-Login" className="w-96 rounded-teaser bg-paper p-6 shadow-popover" onClick={(event) => event.stopPropagation()}>
                <div className="mb-4 flex items-center justify-between">
                    <h2 className="text-head-s font-bold">Anmelden</h2>
                    <Button aria-label="Schließen" onClick={onClose}><Icon name="close" /></Button>
                </div>
                <label className="mb-3 block text-sm">
                    E-Mail-Adresse
                    <input type="email" className="mt-1 block w-full rounded-sm border border-ink-300 px-3 py-2" />
                </label>
                <Button variant="solid" className="w-full justify-center">Weiter</Button>
            </div>
        </div>
    );
}
